// Build title lookup from Get Notion Pages output
const titleLookup = {};
for (const item of $('Get Notion Pages').all()) {
  const page = item.json;
  const props = page.properties || {};
  for (const prop of Object.values(props)) {
    if (prop.type === 'title' && prop.title?.length > 0) {
      titleLookup[page.id] = prop.title.map(t => t.plain_text).join('');
      break;
    }
  }
}

const groups = {};
for (const item of $input.all()) {
  const block = item.json;
  if (!block.content || block.archived || block.in_trash) continue;
  const pageId = block.parent_id || block.root_id;
  if (!pageId) continue;
  if (!groups[pageId]) groups[pageId] = [];
  groups[pageId].push(block.content);
}

return Object.entries(groups)
  .filter(([_, lines]) => lines.length > 0)
  .map(([pageId, lines]) => ({
    json: {
      notion_page_id: pageId,
      notionUrl: "https://www.notion.so/" + pageId.replace(/-/g, ''),
      text: (titleLookup[pageId] ? '# ' + titleLookup[pageId] + '\n\n' : '') +
            lines.join('\n').trim() +
            '\n\nSource: https://www.notion.so/' + pageId.replace(/-/g, '')
    }
  }));
